commands.command:
PW=$(cat /tmp/appdb.pw); RPW=$(cat /tmp/root.pw)
sudo mysql -e "
CREATE DATABASE IF NOT EXISTS appdb;
CREATE TABLE IF NOT EXISTS appdb.orders (id INT PRIMARY KEY AUTO_INCREMENT, item VARCHAR(64), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY [REDACTED]
GRANT ALL PRIVILEGES ON appdb.* TO 'appuser'@'%';
CREATE USER IF NOT EXISTS 'sstuser'@'localhost' IDENTIFIED BY [REDACTED]
GRANT RELOAD, LOCK TABLES, PROCESS, REPLICATION CLIENT ON *.* TO 'sstuser'@'localhost';
FLUSH PRIVILEGES;
"
echo "done"
